function GetMapScriptInfo()
	local world_age, temperature, rainfall, sea_level, resources = GetCoreMapOptions();
	return {
		Name = "TXT_KEY_OB_MAP_NAME",
		Description = "TXT_KEY_OB_MAP_HELP",
		IsAdvancedMap = false,
		SupportsMultiplayer = true,
		IconIndex = 5,
		CustomOptions = {
			{
				Name = "TXT_KEY_OB_MAP_OPTION_START",
				Values = {
					"TXT_KEY_OB_MAP_OPTION_START_HISTORIC",
					"TXT_KEY_OB_MAP_OPTION_START_RANDOM",
				},
				DefaultValue = 1,
				SortPriority = 1,
			},
			resources,
		},
	};
end
